contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run a single test invocation: attempt to sell shares and check invariants when the call succeeds
    function run(uint256 shareAmount, address to, uint256 baseMinAmount, uint256 quoteMinAmount, bytes calldata data, uint256 deadline) external payable {
        require(deadline >= block.timestamp, "pre: deadline must be >= now");

        // Observe balances and totals before
        uint256 totalBefore = c.totalSupply();
        uint256 callerBefore = c.balanceOf(address(this));

        // Ensure caller has enough shares to attempt sell; if not, mint by calling buyShares path is complex so require precondition
        require(shareAmount <= callerBefore, "pre: need caller to hold at least shareAmount");

        // Perform the call and record whether it reverted
        bool reverted;
        uint256 baseOut;
        uint256 quoteOut;
        try c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, data, deadline) returns (uint256 b, uint256 q) {
            reverted = false;
            baseOut = b;
            quoteOut = q;
        } catch {
            reverted = true;
            baseOut = 0;
            quoteOut = 0;
        }

        // After values
        uint256 totalAfter = c.totalSupply();
        uint256 callerAfter = c.balanceOf(address(this));

        // If the call did not revert, then the caller's balance must have decreased by shareAmount and totalSupply decreased by shareAmount
        // If it reverted, we accept no guarantees (so assert implies reverted == true OR invariants hold)
        assert(reverted || (callerBefore - callerAfter == shareAmount && totalBefore - totalAfter == shareAmount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that performs the property check
    function run(address to, uint256 preFundBase, uint256 preFundQuote, uint256 sendBase, uint256 sendQuote) public payable {
        require(address(this).balance >= preFundBase + preFundQuote + sendBase + sendQuote, "insufficient ether for test");
        // We will simulate tokens by calling view functions only; because tokens are external IERC20
        // we cannot mint them here. Instead we focus on observable invariants around buyShares behavior
        // that do not require actual token transfers: we record totalSupply and share balance before,
        // attempt buyShares, and then assert relationships depending on whether it reverted.

        uint256 totalBefore = c.totalSupply();
        uint256 shareBalanceBefore = c.balanceOf(to);

        bool reverted = false;
        uint256 retShares;
        uint256 retBaseInput;
        uint256 retQuoteInput;
        // attempt the call; it may revert for many reasons (NO_BASE_INPUT, MINT_AMOUNT_NOT_ENOUGH, etc.)
        try c.buyShares(to) returns (uint256 shares, uint256 baseInput, uint256 quoteInput) {
            reverted = false;
            retShares = shares;
            retBaseInput = baseInput;
            retQuoteInput = quoteInput;
        } catch {
            reverted = true;
        }

        uint256 totalAfter = c.totalSupply();
        uint256 shareBalanceAfter = c.balanceOf(to);

        // General rule:
        // - If buyShares reverted, totalSupply and share balance must be unchanged.
        // - If buyShares succeeded, shareBalanceAfter == shareBalanceBefore + retShares,
        //   and totalAfter >= totalBefore + retShares (totalSupply increases by at least minted amount).
        assert(
            (reverted && totalAfter == totalBefore && shareBalanceAfter == shareBalanceBefore)
            || (!reverted && shareBalanceAfter == shareBalanceBefore + retShares && totalAfter >= totalBefore + retShares)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test transferFrom behavior for shares: caller is this contract (msg.sender when calling c)
    // Params: from - source address that must have enough shares; spender - this contract must be approved
    // amount - amount to transfer
    function run(address from, address to, uint256 amount) public payable {
        require(from != address(0) && to != address(0), "invalid addr");

        // Observe balances and allowance before
        uint256 fromBalBefore = c.balanceOf(from);
        uint256 toBalBefore = c.balanceOf(to);
        uint256 allowanceBefore = c.allowance(from, address(this));

        // Call transferFrom and catch revert
        bool reverted = false;
        try c.transferFrom(from, to, amount) returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 fromBalAfter = c.balanceOf(from);
        uint256 toBalAfter = c.balanceOf(to);
        uint256 allowanceAfter = c.allowance(from, address(this));

        // General rule:
        // If transferFrom reverted then balances and allowance unchanged.
        // If it succeeded then: from balance decreased by exactly amount, to balance increased by exactly amount,
        // and allowance decreased by exactly amount (but not below zero) unless allowanceBefore was type(uint256).max (infinite allowance), in which case allowance stays unchanged.
        assert(
            (reverted && fromBalAfter == fromBalBefore && toBalAfter == toBalBefore && allowanceAfter == allowanceBefore)
            || (!reverted && fromBalAfter + amount == fromBalBefore && toBalAfter == toBalBefore + amount &&
                (allowanceBefore == type(uint256).max ? allowanceAfter == allowanceBefore : allowanceAfter + amount == allowanceBefore))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We call buyShares(to) which may revert; ensure that on success the vault reserves match token balances net of mt fees,
    // and on revert the vault reserves are unchanged.
    function run(address to) public payable {
        require(to != address(0), "zero to");

        // Read pre-state reserves
        (uint256 baseReserveBefore, uint256 quoteReserveBefore) = c.getVaultReserve();
        (uint256 mtFeeBaseBefore, uint256 mtFeeQuoteBefore) = c.getMtFeeTotal();

        bool reverted;
        uint256 shares;
        uint256 baseInput;
        uint256 quoteInput;

        try c.buyShares(to) returns (uint256 _shares, uint256 _baseInput, uint256 _quoteInput) {
            reverted = false;
            shares = _shares;
            baseInput = _baseInput;
            quoteInput = _quoteInput;
        } catch {
            reverted = true;
        }

        (uint256 baseReserveAfter, uint256 quoteReserveAfter) = c.getVaultReserve();
        (uint256 mtFeeBaseAfter, uint256 mtFeeQuoteAfter) = c.getMtFeeTotal();

        // Observe token balances of the vault via public token getters
        // Note: calling c._BASE_TOKEN_ or _BASE_RESERVE_ directly is not allowed; use public getters available.
        // GSPVault exposes getVaultReserve and getMtFeeTotal only; but we can read address(c).balance for ETH held
        // The rule: if buyShares succeeded, reserves increased to equal previous balances of tokens minus mt fees.
        // We express observable condition: if reverted then reserves unchanged and mt fees unchanged; else reserves changed (or equal) and mt fees may change.

        // Final single assert: if reverted -> reserves and mt fees equal before; if not reverted -> reservesAfter >= baseReserveBefore and quoteReserveAfter >= quoteReserveBefore
        assert(
            (reverted && baseReserveAfter == baseReserveBefore && quoteReserveAfter == quoteReserveBefore && mtFeeBaseAfter == mtFeeBaseBefore && mtFeeQuoteAfter == mtFeeQuoteBefore)
            ||
            (!reverted && baseReserveAfter >= baseReserveBefore && quoteReserveAfter >= quoteReserveBefore)
        );
    }

    receive() external payable {}
}
